            modelBuilder.Entity("MysticRealms.Domain.CharacterClasses.CharacterClass", b =>
                {
                    b.Property<int>("Id")
                        .HasColumnType("int");

                    b.Property<string>("Description")
                        .IsRequired()
                        .HasMaxLength(1000)
                        .HasColumnType("nvarchar(1000)");

                    b.Property<int>("Energy")
                        .HasColumnType("int");

                    b.Property<int>("HitPoints")
                        .HasColumnType("int");

                    b.Property<string>("Name")
                        .IsRequired()
                        .HasMaxLength(100)
                        .HasColumnType("nvarchar(100)");

                    b.Property<int>("Order")
                        .HasColumnType("int");

                    b.Property<int>("Speed")
                        .HasColumnType("int");

                    b.HasKey("Id");

                    b.ToTable("CharacterClasses");

                    b.HasData(
                        new
                        {
                            Id = 1,
                            Description = "The Warrior class balances offense and defense, using their sturdy armor and precise strikes to withstand attacks while dealing consistent damage. They excel at adaptability, shielding allies and seizing opportunities to strike.",
                            Energy = 3,
                            HitPoints = 80,
                            Name = "Warrior",
                            Order = 0,
                            Speed = 6
                        },
                        new
                        {
                            Id = 2,
                            Description = "The Assassin class excels in delivering rapid, high-impact attacks and inflicting poison to weaken enemies over time. Their abilities are designed for efficiency, with low mana costs allowing for sustained offensive pressure. Assassins thrive on dealing burst damage and outlasting opponents through relentless assaults.",
                            Energy = 3,
                            HitPoints = 60,
                            Name = "Assassin",
                            Order = 1,
                            Speed = 9
                        },
                        new
                        {
                            Id = 3,
                            Description = "The Ranger class specializes in precision and versatility, excelling at landing critical strikes and dealing damage to multiple targets. With their keen aim and tactical prowess, Rangers are adept at controlling the battlefield, taking down enemies swiftly and efficiently.",
                            Energy = 3,
                            HitPoints = 70,
                            Name = "Ranger",
                            Order = 6,
                            Speed = 8
                        },
                        new
                        {
                            Id = 4,
                            Description = "The Paladin class is a resilient combatant, specializing in empowering themselves through potent buffs and self-healing abilities. With a focus on durability and sustained strength, Paladins excel at enduring prolonged battles while maintaining their own vitality. Their abilities make them ideal for those who value self-reliance and unwavering perseverance on the battlefield.",
                            Energy = 3,
                            HitPoints = 90,
                            Name = "Paladin",
                            Order = 7,
                            Speed = 5
                        },
                        new
                        {
                            Id = 5,
                            Description = "The White Mage class is a supportive powerhouse, specializing in healing and empowering allies with powerful buffs. While their primary role focuses on restoring health and enhancing team effectiveness, they also possess a few offensive abilities for self-defense and contributing to the fight. White Mages shine as the heart of any team, ensuring allies stay strong and capable in battle.",
                            Energy = 3,
                            HitPoints = 50,
                            Name = "White Mage",
                            Order = 8,
                            Speed = 4
                        },
                        new
                        {
                            Id = 6,
                            Description = "The Black Mage class wields devastating magical attacks, harnessing the elements to deal massive damage to enemies. They also tap into the dark art of blood magic, sacrificing a portion of their own vitality to restore their power and sustain their offensive onslaught. Black Mages excel at overwhelming foes with raw magical force while maintaining their strength through calculated risk and mastery of forbidden techniques.",
                            Energy = 3,
                            HitPoints = 40,
                            Name = "Black Mage",
                            Order = 5,
                            Speed = 5
                        },
                        new
                        {
                            Id = 7,
                            Description = "The Elementalist class commands the four primal elements, each offering unique versatility in battle. Earth provides defensive abilities to withstand attacks, Fire delivers devastating single-target damage, Air unleashes multi-target assaults to control the battlefield, and Water offers restorative powers to heal and sustain. Elementalists excel at adapting to any situation, making them a versatile and dynamic force in combat.",
                            Energy = 3,
                            HitPoints = 60,
                            Name = "Elementalist",
                            Order = 2,
                            Speed = 7
                        },
                        new
                        {
                            Id = 8,
                            Description = "The Druid class harnesses the power of nature and its creatures to influence the battlefield. They specialize in buffing allies with empowering effects while crippling enemies with potent debuffs. With their deep connection to the natural world, Druids excel at providing versatile support and controlling the flow of combat, ensuring their team has the upper hand.",
                            Energy = 3,
                            HitPoints = 70,
                            Name = "Druid",
                            Order = 3,
                            Speed = 6
                        },
                        new
                        {
                            Id = 9,
                            Description = "The Barbarian class unleashes raw power through massive, high-damage attacks, prioritizing offense over defense. With their relentless aggression and devastating strikes, Barbarians excel at overwhelming enemies quickly. However, their limited defensive abilities require careful timing and positioning to maximize their destructive potential on the battlefield.",
                            Energy = 3,
                            HitPoints = 100,
                            Name = "Barbarian",
                            Order = 4,
                            Speed = 7
                        },
                        new
                        {
                            Id = 10,
                            Description = "The Engineer class is a versatile problem solver, excelling as a jack-of-all-trades on the battlefield. Using their ingenuity and creativity, they adapt to any situation with unique tools and clever strategies. Engineers thrive in unpredictable scenarios, offering a balanced mix of utility, offense, and support to turn the tide of battle.",
                            Energy = 3,
                            HitPoints = 70,
                            Name = "Engineer",
                            Order = 9,
                            Speed = 6
                        });
                });

